#!/usr/bin/env python3
"""PS1A0: test each signed-minor axis against its matching marked-cut continuation."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
chain=json.loads((ROOT/'research/benincasa/three-cut-relative-chain-pairing-certificate.json').read_text());lifts=json.loads((ROOT/'research/benincasa/physical-cycle-endpoint-normal-lifts.json').read_text());unique=(ROOT/'research/benincasa/published_boundary_value_leray_uniqueness.md').read_text()
marked=chain['marked_cuts'];incidence={'c=0':{'cut':'q_G12','equation':marked['q_G12'],'limit':'c=-E -> 0','jacobian':'dc','multiplicity':1},'a=0':{'cut':'q_G23','equation':marked['q_G23'],'limit':'a=-E -> 0','jacobian':'da','multiplicity':1},'b=0':{'cut':'q_G31','equation':marked['q_G31'],'limit':'b=-E -> 0','jacobian':'db','multiplicity':1}}
checks={'three_matching_cuts':marked=={'q_G12':'E+c','q_G23':'E+a','q_G31':'E+b'},'three_axis_faces':{x['endpoint'] for x in lifts['checks']}==set(incidence),'endpoint_lifts_tangent':lifts['incidence_tangency_checks']==9,'negative_imaginary_orientation_unique':'multiplicity one' in unique and 'Im}q<0' in unique,'unit_transverse_jacobians':all(x['multiplicity']==1 for x in incidence.values())}
