out={'schema':'marici.benincasa.PS1A0-alternate-signed-minor-incidence.v1','prospective_action':'PS1A0_axis_incidence','outcome_contract':{'++':'each endpoint axis is reached transversely by its matching source marked-cut continuation','+-':'some but not all axes are reached','-+':'matching marked cuts miss the axes','--':'incidence cannot be typed'},'resolution':'++','incidence':incidence,'distinction_from_failed_channel':'VC2m1 tested a=0,b=0 against the q_G12 marked-corner blowup centered at (a,b)=(y,x), which they miss. PS1A0 instead uses the matching q_G23 and q_G31 cuts, whose equations directly specialize to those axes.','established':'All three axes have source-oriented transverse marked-cut germs with unit local multiplicity.','withheld':'Incidence does not yet glue the three local germs into one global physical relative current or pair it with the degree-15 correction.','next':'PS1A1 construct the three matching source Leray germs and compare their oriented boundary vector with the degree-15 collar correction.','checks':checks,'passed':True};p=ROOT/'research/benincasa/results/PS1A0_alternate_signed_minor_incidence.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'passed':True,'resolution':'++','axes':3,'multiplicities':[1,1,1],'next':'PS1A1_matching_source_Leray_germs'}))
